package com.cinenest.payments.internal;
import java.sql.*;
import java.time.*;
import java.util.*;
import com.nimbusds.jose.util.JSONObjectUtils;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;
@Repository
class JdbcBankRepository implements BankRepository {
 private final JdbcClient jdbc;JdbcBankRepository(JdbcClient jdbc){this.jdbc=jdbc;}
 private JdbcClient.StatementSpec sql(String s,Object... p){var q=jdbc.sql(s);for(int i=0;i<p.length;i+=2)q=q.param(p[i].toString(),p[i+1] instanceof Instant t?t.atOffset(ZoneOffset.UTC):p[i+1]);return q;}
 private static Instant time(ResultSet r,String n)throws SQLException{return r.getTimestamp(n).toInstant();}
 private static Map<String,Object> json(String s){try{return JSONObjectUtils.parse(s);}catch(Exception e){throw new IllegalStateException(e);}}
 private static Request request(ResultSet r,int i)throws SQLException{return new Request(r.getObject("request_id",UUID.class),r.getObject("owner_id",UUID.class),r.getObject("venue_id",UUID.class),r.getObject("quote_id",UUID.class),r.getObject("hold_id",UUID.class),r.getObject("policy_id",UUID.class),r.getLong("revision"),r.getString("state"),r.getString("review_state"),time(r,"initiate_by"),time(r,"expires_at"),time(r,"submit_by"),time(r,"review_by"),time(r,"escalate_at"),time(r,"hold_until"),r.getString("timezone"),r.getString("amount_minor"),r.getString("currency"),json(r.getString("snapshot")));}
 private static Claim claim(ResultSet r,int i)throws SQLException{return new Claim(r.getObject("claim_id",UUID.class),r.getObject("request_id",UUID.class),r.getInt("generation"),time(r,"submitted_at"));}
 private static Evidence evidence(ResultSet r,int i)throws SQLException{return new Evidence(r.getObject("evidence_id",UUID.class),r.getObject("request_id",UUID.class),r.getObject("claim_id",UUID.class),r.getObject("object_key",UUID.class),r.getObject("preview_key",UUID.class),r.getString("state"),time(r,"expires_at"),time(r,"retain_until"),r.getString("mime"));}
 public Map<String,Object> policy(UUID id){return sql("SELECT policy::text FROM cinenest_payments.bank_policy_revision WHERE policy_id=:id","id",id).query((r,i)->json(r.getString(1))).single();}
 public Instant now(){return jdbc.sql("SELECT clock_timestamp()").query(OffsetDateTime.class).single().toInstant();}
 public Optional<Request> request(UUID id,boolean lock){return sql("SELECT * FROM cinenest_payments.bank_payment_request WHERE request_id=:id"+(lock?" FOR UPDATE":""),"id",id).query(JdbcBankRepository::request).optional();}
 public Optional<Claim> claim(UUID id){return sql("SELECT * FROM cinenest_payments.bank_receipt_claim WHERE claim_id=:id","id",id).query(JdbcBankRepository::claim).optional();}
 public Optional<Claim> latest(UUID id){return sql("SELECT * FROM cinenest_payments.bank_receipt_claim WHERE request_id=:id ORDER BY generation DESC LIMIT 1","id",id).query(JdbcBankRepository::claim).optional();}
 public List<Request> owned(UUID owner,int offset,int limit){return sql("SELECT * FROM cinenest_payments.bank_payment_request WHERE owner_id=:a ORDER BY created_at DESC,request_id DESC LIMIT :n OFFSET :o","a",owner,"n",limit,"o",offset).query(JdbcBankRepository::request).list();}
 public List<Request> queue(UUID venue,UUID actor){return sql("SELECT * FROM cinenest_payments.bank_payment_request WHERE venue_id=:v AND owner_id<>:a ORDER BY LEAST(review_by,escalate_at),COALESCE((SELECT min(submitted_at) FROM cinenest_payments.bank_receipt_claim c WHERE c.request_id=bank_payment_request.request_id),created_at),request_id LIMIT 100","v",venue,"a",actor).query(JdbcBankRepository::request).list();}
 public List<Evidence> evidence(UUID id){return sql("SELECT * FROM cinenest_payments.bank_receipt_evidence WHERE claim_id=:id ORDER BY position","id",id).query(JdbcBankRepository::evidence).list();}
 public Optional<Evidence> upload(UUID id,boolean lock){return sql("SELECT * FROM cinenest_payments.bank_receipt_evidence WHERE evidence_id=:id"+(lock?" FOR UPDATE":""),"id",id).query(JdbcBankRepository::evidence).optional();}
 public void create(UUID id,com.cinenest.pricing.BankQuotation.Facts q,BankPolicy.Policy p,Map<String,Instant> t){
  sql("INSERT INTO cinenest_payments.bank_policy_revision(policy_id,version,content_hash,policy,synthetic) VALUES(:id,:v,:h,CAST(:p AS jsonb),TRUE) ON CONFLICT(policy_id) DO NOTHING","id",p.id(),"v",p.version(),"h",p.hash(),"p",JSONObjectUtils.toJSONString(Map.of("version",p.version(),"reviewWindow",p.opens()+"–"+p.closes(),"policy",p.toString(),"synthetic",true))).update();
  sql("INSERT INTO cinenest_payments.bank_payment_request(request_id,owner_id,venue_id,quote_id,hold_id,policy_id,quote_revision,quote_hash,snapshot,amount_minor,currency,timezone,instruction_version,expires_at,initiate_by,submit_by,review_by,escalate_at,hold_until,state,review_state) VALUES(:id,:a,:v,:q,:hold,:p,:rev,:hash,CAST(:snapshot AS jsonb),:amount,'LKR',:zone,:instructions,:expires,:initiate,:submit,:review,:escalate,:until,'OPEN','PENDING')","id",id,"a",q.owner(),"v",q.venue(),"q",q.quote(),"hold",q.hold(),"p",p.id(),"rev",q.revision(),"hash",q.hash(),"snapshot",JSONObjectUtils.toJSONString(q.snapshot()),"amount",Long.parseLong(q.snapshot().get("totalMinor").toString()),"zone",q.snapshot().get("timezone"),"instructions",p.version(),"expires",t.get("expires"),"initiate",t.get("initiate"),"submit",t.get("submit"),"review",t.get("review"),"escalate",t.get("escalate"),"until",t.get("hold")).update();
 }
 public void claim(UUID id,UUID request,int generation,long amount,Instant paid,String reference){sql("INSERT INTO cinenest_payments.bank_receipt_claim(claim_id,request_id,generation,declared_amount_minor,declared_paid_at,declared_reference) VALUES(:id,:r,:g,:a,:p,:ref)","id",id,"r",request,"g",generation,"a",amount,"p",paid,"ref",reference).update();}
 public void allocate(Evidence e,int position){sql("INSERT INTO cinenest_payments.bank_receipt_evidence(evidence_id,request_id,claim_id,position,object_key,preview_key,state,expires_at,retain_until) VALUES(:id,:r,:c,:p,:o,:preview,'ALLOCATED',:expires,:retain)","id",e.id(),"r",e.request(),"c",e.claim(),"p",position,"o",e.object(),"preview",e.preview(),"expires",e.expires(),"retain",e.retain()).update();}
 public void uploaded(UUID id,String digest,String mime,int bytes){sql("UPDATE cinenest_payments.bank_receipt_evidence SET state='QUARANTINED',digest=:digest,mime=:mime,byte_size=:bytes,revision=revision+1 WHERE evidence_id=:id","id",id,"digest",digest,"mime",mime,"bytes",bytes).update();}
 public void evidenceState(UUID id,String state){sql("UPDATE cinenest_payments.bank_receipt_evidence SET state=:s,revision=revision+1 WHERE evidence_id=:id","id",id,"s",state).update();}
 public boolean timely(UUID claim,Instant deadline){return sql("SELECT count(*)>0 AND bool_and(completed_at IS NOT NULL AND completed_at<=:deadline) FROM cinenest_payments.bank_receipt_evidence WHERE claim_id=:claim","claim",claim,"deadline",deadline).query(Boolean.class).single();}
 public void completeEvidence(UUID id){sql("UPDATE cinenest_payments.bank_receipt_evidence SET completed_at=clock_timestamp(),revision=revision+1 WHERE evidence_id=:id AND completed_at IS NULL","id",id).update();}
 public boolean duplicate(UUID id){return sql("SELECT EXISTS(SELECT 1 FROM cinenest_payments.bank_receipt_evidence a JOIN cinenest_payments.bank_receipt_evidence b ON a.digest=b.digest AND a.evidence_id<>b.evidence_id AND a.request_id=b.request_id WHERE a.evidence_id=:id)","id",id).query(Boolean.class).single();}
 public void transition(UUID id,String state,String review){sql("UPDATE cinenest_payments.bank_payment_request SET state=:s,review_state=:review,revision=revision+1 WHERE request_id=:id","id",id,"s",state,"review",review).update();}
 public void decision(Request r,UUID claim,UUID actor,String action,String reason,UUID handover){sql("INSERT INTO cinenest_payments.bank_review_decision(decision_id,request_id,claim_id,actor_id,handover_to,revision,action,reason) VALUES(:id,:r,:c,:a,:handover,:rev,:action,:reason)","id",UUID.randomUUID(),"r",r.id(),"c",claim,"a",actor,"handover",handover,"rev",r.revision(),"action",action,"reason",reason).update();}
 public List<Map<String,Object>> workSummary(UUID id){return sql("SELECT work_id,kind,state,attempts,due_at FROM cinenest_payments.bank_work WHERE request_id=:id ORDER BY due_at,work_id","id",id).query((r,i)->Map.<String,Object>of("id",r.getString(1),"kind",r.getString(2),"state",r.getString(3),"attempts",r.getInt(4),"dueAt",r.getString(5))).list();}
 public List<Map<String,Object>> history(UUID id){return sql("SELECT decision_id,actor_id,action,reason,recorded_at,COALESCE(handover_to::text,'') FROM cinenest_payments.bank_review_decision WHERE request_id=:id ORDER BY revision","id",id).query((r,i)->Map.<String,Object>of("id",r.getString(1),"actor",r.getString(2),"action",r.getString(3),"reason",r.getString(4),"at",r.getString(5),"handoverTo",r.getString(6))).list();}
 public List<Map<String,Object>> claims(UUID request){return sql("SELECT claim_id,generation,declared_amount_minor,declared_paid_at,submitted_at FROM cinenest_payments.bank_receipt_claim WHERE request_id=:id ORDER BY generation","id",request).query((r,i)->Map.<String,Object>of("id",r.getString(1),"generation",r.getInt(2),"declaredAmountMinor",r.getString(3),"declaredPaidAt",r.getString(4),"receivedAt",r.getString(5))).list();}
 public Optional<Map<String,Object>> command(UUID actor,UUID key,String hash){return sql("SELECT content_hash,response::text FROM cinenest_payments.bank_command WHERE actor_id=:a AND command_key=:k","a",actor,"k",key).query((r,i)->{if(!hash.equals(r.getString(1)))throw new BankFailure(409,"Idempotency key payload changed");return json(r.getString(2));}).optional();}
 public void command(UUID actor,UUID key,String hash,Map<String,Object> result){sql("INSERT INTO cinenest_payments.bank_command(actor_id,command_key,content_hash,response) VALUES(:a,:k,:h,CAST(:r AS jsonb))","a",actor,"k",key,"h",hash,"r",JSONObjectUtils.toJSONString(result)).update();}
 public void audit(UUID actor,UUID request,String action,String result){sql("INSERT INTO cinenest_payments.bank_audit VALUES(:id,:a,:r,:action,:result,:correlation,clock_timestamp())","id",UUID.randomUUID(),"a",actor,"r",request,"action",action,"result",result,"correlation",UUID.randomUUID()).update();}
 public void work(UUID request,UUID evidence,String kind,Instant due){sql("INSERT INTO cinenest_payments.bank_work(work_id,request_id,evidence_id,kind,state,due_at) VALUES(:id,:r,:e,:kind,'PENDING',:due) ON CONFLICT(evidence_id,kind) DO NOTHING","id",UUID.randomUUID(),"r",request,"e",evidence,"kind",kind,"due",due).update();}
 public List<Map<String,Object>> pending(){return jdbc.sql("SELECT work_id,request_id,evidence_id,kind FROM cinenest_payments.bank_work WHERE due_at<=clock_timestamp() AND (state IN ('PENDING','FAILED') OR (state='RUNNING' AND lease_until<clock_timestamp())) ORDER BY due_at LIMIT 100").query((r,i)->{Map<String,Object> m=new HashMap<>();m.put("id",r.getObject(1,UUID.class));m.put("request",r.getObject(2,UUID.class));m.put("evidence",r.getObject(3,UUID.class));m.put("kind",r.getString(4));return m;}).list();}
 public int claimWork(UUID id,Instant until){return sql("UPDATE cinenest_payments.bank_work SET state='RUNNING',attempts=attempts+1,lease_until=:until,updated_at=clock_timestamp() WHERE work_id=:id AND (state IN ('PENDING','FAILED') OR (state='RUNNING' AND lease_until<clock_timestamp())) RETURNING attempts","id",id,"until",until).query(Integer.class).optional().orElse(0);}
 public boolean owns(UUID id,int attempt){return sql("SELECT attempts FROM cinenest_payments.bank_work WHERE work_id=:id AND attempts=:attempt AND state='RUNNING' FOR UPDATE","id",id,"attempt",attempt).query(Integer.class).optional().isPresent();}
 public void workState(UUID id,String state,Instant due){sql("UPDATE cinenest_payments.bank_work SET state=:s,due_at=:due,updated_at=clock_timestamp() WHERE work_id=:id","id",id,"s",state,"due",due).update();}
 public List<Evidence> cleanup(){return jdbc.sql("SELECT * FROM cinenest_payments.bank_receipt_evidence WHERE state<>'DELETED' AND (retain_until<=clock_timestamp() OR (state IN ('ALLOCATED','UPLOADING') AND expires_at<=clock_timestamp()) OR state IN ('DELETION_PENDING','CLEANUP_FAILED')) LIMIT 100").query(JdbcBankRepository::evidence).list();}
 public boolean referenced(UUID key){return sql("SELECT count(*) FROM cinenest_payments.bank_receipt_evidence WHERE (object_key=:k OR preview_key=:k) AND state<>'DELETED'","k",key).query(Integer.class).single()>0;}
 public List<Request> expiring(){return jdbc.sql("SELECT * FROM cinenest_payments.bank_payment_request WHERE expires_at<=clock_timestamp() AND state NOT IN ('EXPIRED','CANCELLED') LIMIT 100").query(JdbcBankRepository::request).list();}
}
